export const selectPurchasedConsultPolicy = (
  policies: readonly Policys[],
  planId: string,
): Policys | undefined =>
  policies
    .filter((policy: Policys): boolean => policy.plan.id === planId)
    .reduce<Policys | undefined>((latest: Policys | undefined, policy: Policys) => {
      if (!latest || policyEffectiveTime(policy) >= policyEffectiveTime(latest)) {
        return policy;
      }

      return latest;
    }, undefined);

export interface ConsultOperatedPlanTarget {
  insurancePolicyId?: string;
  membershipId?: string;
  planId?: string;
  policyId?: string;
}

const readObject = (value: unknown): Record<string, unknown> | undefined => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return undefined;
  }

  return value as Record<string, unknown>;
};

const readTrimmedString = (value: unknown): string | undefined =>
  typeof value === 'string' && value.trim().length > 0
    ? value.trim()
    : undefined;

const firstPlanId = (
  ...values: Array<string | undefined>
): string | undefined => {
  for (const value of values) {
    const trimmed = value?.trim();

    if (trimmed) {
      return trimmed;
    }
  }

  return undefined;
};

const selectLatestPolicy = (
  policies: readonly Policys[],
): Policys | undefined =>
  policies.reduce<Policys | undefined>(
    (latest: Policys | undefined, policy: Policys) => {
      if (!latest || policyEffectiveTime(policy) >= policyEffectiveTime(latest)) {
        return policy;
      }

      return latest;
    },
    undefined,
  );

export const mergeConsultOperatedPlanTargets = (
  preferred?: ConsultOperatedPlanTarget,
  fallback?: ConsultOperatedPlanTarget,
): ConsultOperatedPlanTarget | undefined => {
  const policyId = firstPlanId(preferred?.policyId, fallback?.policyId);
  const insurancePolicyId = firstPlanId(
    preferred?.insurancePolicyId,
    fallback?.insurancePolicyId,
  );
  const planId = firstPlanId(preferred?.planId, fallback?.planId);
  const membershipId = firstPlanId(
    preferred?.membershipId,
    fallback?.membershipId,
  );

  if (!policyId && !insurancePolicyId && !planId && !membershipId) {
    return undefined;
  }

  return {
    insurancePolicyId,
    membershipId,
    planId,
    policyId,
  };
};

export const readActivatedConsultPlanTarget = (
  response: unknown,
): ConsultOperatedPlanTarget | undefined => {
  const responseRecord = readObject(response);
  const dataRecord = readObject(responseRecord?.data);
  const candidates = [
    responseRecord,
    dataRecord,
    readObject(dataRecord?.policy),
    readObject(responseRecord?.policy),
  ];

  for (const candidate of candidates) {
    if (!candidate) {
      continue;
    }

    const policyId = readTrimmedString(candidate.policyId);
    const planId =
      readTrimmedString(candidate.planId) ??
      readTrimmedString(readObject(candidate.plan)?.id);

    if (policyId || planId) {
      return mergeConsultOperatedPlanTargets({ planId, policyId });
    }
  }

  return undefined;
};

export const resolveConsultOperatedPolicy = (
  policies: readonly Policys[],
  target: ConsultOperatedPlanTarget,
): Policys | undefined => {
  const policyId = target.policyId?.trim();

  if (policyId) {
    const matchedPolicy = policies.find(
      (policy: Policys): boolean => policy.id === policyId,
    );

    if (matchedPolicy) {
      return matchedPolicy;
    }
  }

  const insurancePolicyId = target.insurancePolicyId?.trim();

  if (insurancePolicyId) {
    const matchedPolicy = policies.find(
      (policy: Policys): boolean => policy.id === insurancePolicyId,
    );

    if (matchedPolicy) {
      return matchedPolicy;
    }
  }

  const membershipId = target.membershipId?.trim();

  if (membershipId) {
    const matchedPolicy = policies.find(
      (policy: Policys): boolean => policy.memberShipId === membershipId,
    );

    if (matchedPolicy) {
      return matchedPolicy;
    }
  }

  const planId = target.planId?.trim();

  if (!planId) {
    return undefined;
  }

  return selectPurchasedConsultPolicy(policies, planId);
};

export const selectNewlyActivatedConsultPolicy = (
  previousPolicies: readonly Policys[] | undefined,
  nextPolicies: readonly Policys[],
  hint?: ConsultOperatedPlanTarget,
): Policys | undefined => {
  if (previousPolicies) {
    const previousPolicyIds = new Set(
      previousPolicies.map((policy: Policys): string => policy.id),
    );
    const createdPolicies = nextPolicies.filter(
      (policy: Policys): boolean => !previousPolicyIds.has(policy.id),
    );
    const hintedCreatedPolicy = hint
      ? resolveConsultOperatedPolicy(createdPolicies, hint)
      : undefined;

    if (hintedCreatedPolicy) {
      return hintedCreatedPolicy;
    }

    // An empty snapshot plus several current policies is not evidence that
    // every policy was just activated.
    if (!(previousPolicies.length === 0 && createdPolicies.length > 1)) {
      const latestCreatedPolicy = selectLatestPolicy(createdPolicies);

      if (latestCreatedPolicy) {
        return latestCreatedPolicy;
      }
    }
  }

  return hint
    ? resolveConsultOperatedPolicy(nextPolicies, hint)
    : undefined;
};

