import React, { useEffect, useState } from 'react';
import { ActivityIndicator, View } from 'react-native';

import NavigationBar from '@components/navigation-bar/navigation-bar';
import constants from '@constants';
import type { ScreenProps } from '@navigation/types';
import {
  fetchSelectableBenefitPlans,
  resolveConsultOperatedPolicy,
  type ConsultOperatedPlanTarget,
} from '@services/benefit-plan-service';
import { useAppState } from '@store/AppContext';
import { ThemeContext } from '@style/theme/theme-context';
import type { Theme } from '../../types/Theme';

import ConsultBrowser from './consult-browser';
import styles, { getConsultScreenThemeStyles } from './consult-screen.styles';

const OPERATED_PLAN_ATTEMPTS = 3;
const OPERATED_PLAN_RETRY_DELAY_MS = 300;

type ConsultSecondaryScreenProps = Partial<
  ScreenProps<typeof $routeNames.consultSecondary>
>;

const hasOperatedPlanTarget = (
  target: ConsultOperatedPlanTarget | undefined,
): target is ConsultOperatedPlanTarget =>
  [
    target?.policyId,
    target?.insurancePolicyId,
    target?.planId,
    target?.membershipId,
  ].some(
    (value: string | undefined): boolean =>
      typeof value === 'string' && value.trim().length > 0,
  );

const wait = (delayMs: number): Promise<void> =>
  new Promise((resolve): void => {
    setTimeout(resolve, delayMs);
  });

const ConsultSecondaryScreen = ({
  route,
}: ConsultSecondaryScreenProps = {}): React.ReactElement => {
  const { language, setPlan, setSelectedPolicies } = useAppState();
  const operatedPlan = route?.params?.operatedPlan;
  const shouldSelectOperatedPlan = hasOperatedPlanTarget(operatedPlan);
  const [isOperatedPlanReady, setIsOperatedPlanReady] = useState(
    !shouldSelectOperatedPlan,
  );
  const title = constants.i18n.t('consult', {
    locale: language ?? constants.i18n.locale,
  });
  const operatedPolicyId = operatedPlan?.policyId;
  const operatedInsurancePolicyId = operatedPlan?.insurancePolicyId;
  const operatedPlanId = operatedPlan?.planId;
  const operatedMembershipId = operatedPlan?.membershipId;

  useEffect((): (() => void) | undefined => {
    if (!shouldSelectOperatedPlan) {
      return undefined;
    }

    let active = true;
    const target: ConsultOperatedPlanTarget = {
      insurancePolicyId: operatedInsurancePolicyId,
      membershipId: operatedMembershipId,
      planId: operatedPlanId,
      policyId: operatedPolicyId,
    };

    const applyOperatedPlan = async (): Promise<void> => {
      setIsOperatedPlanReady(false);

      try {
        for (let attempt = 0; attempt < OPERATED_PLAN_ATTEMPTS; attempt += 1) {
          if (!active) {
            return;
          }

          let policies: Awaited<ReturnType<typeof fetchSelectableBenefitPlans>> =
            [];

          try {
            policies = await fetchSelectableBenefitPlans();
          } catch (_error) {
            policies = [];
          }

          if (!active) {
            return;
          }

          const matchedPolicy = resolveConsultOperatedPolicy(policies, target);

          if (matchedPolicy) {
            setPlan(matchedPolicy.plan);
            setSelectedPolicies(matchedPolicy);
            break;
          }

          if (attempt < OPERATED_PLAN_ATTEMPTS - 1) {
            await wait(OPERATED_PLAN_RETRY_DELAY_MS);
          }
        }
      } finally {
        if (active) {
          setIsOperatedPlanReady(true);
        }
      }
    };

    applyOperatedPlan().then();

    return (): void => {
      active = false;
    };
  }, [
    operatedInsurancePolicyId,
    operatedMembershipId,
    operatedPlanId,
    operatedPolicyId,
    setPlan,
    setSelectedPolicies,
    shouldSelectOperatedPlan,
  ]);

  return (
    <ThemeContext.Consumer>
      {(theme: Theme): React.ReactElement => (
        <View style={styles.secondaryPage} testID="consult-secondary-screen">
          <NavigationBar title={title} />
          <View
            style={[
              theme.uiTheme?.commonStyles.pageContainer,
              styles.page,
              getConsultScreenThemeStyles(theme).page,
            ]}
          >
            {isOperatedPlanReady ? (
              <ConsultBrowser />
            ) : (
              <View
                style={styles.operatedPlanLoading}
                testID="consult-operated-plan-loading"
              >
                <ActivityIndicator color="#00AC86" />
              </View>
            )}
          </View>
        </View>
      )}
    </ThemeContext.Consumer>
  );
};

