    ...createPolicy('older-policy', 'consult-plan'),
    effectiveDate: '2026-10-01T00:00:00.000Z',
    memberShipId: 'HP-OLD',
  };
  const newerPolicy = {
    ...createPolicy('newer-policy', 'consult-plan'),
    effectiveDate: '2026-10-20T00:00:00.000Z',
    memberShipId: 'HP-NEW',
  };
  const policies = [olderPolicy, newerPolicy];

  expect(
    resolveConsultOperatedPolicy(policies, { policyId: 'older-policy' }),
  ).toBe(olderPolicy);
  expect(
    resolveConsultOperatedPolicy(policies, {
      insurancePolicyId: 'newer-policy',
    }),
  ).toBe(newerPolicy);
  expect(
    resolveConsultOperatedPolicy(policies, { membershipId: 'HP-OLD' }),
  ).toBe(olderPolicy);
  expect(
    resolveConsultOperatedPolicy(policies, { planId: 'consult-plan' }),
  ).toBe(newerPolicy);
